      ModeYTimelineReport();   /* NORTH STAR 1's measurement -- see g_ytl_* */
      cursor = LogPut(cursor, "STAGE2: modeY remap="); cursor = LogHex(cursor, (DWORD)g_ModeYRemap);
      cursor = LogPut(cursor, " swaps="); cursor = LogHex(cursor, g_ModeYSwaps);
