          cursor = LogPut(cursor, " cross_same="); cursor = LogHex(cursor, g_ModeYSampleCrossSame[bnd]);
          cursor = LogPut(cursor, " cross_diff="); cursor = LogHex(cursor, g_ModeYSampleCrossDiff[bnd]);
          cursor = LogPut(cursor, " cross_eqb=");
